#include <stdio.h>
#include <stdlib.h>

int is_perfect(int n) {
    int sum = 0;
    for (int i = 1; i < n; i++) {
        if (n % i == 0) {
            sum += i;
        }
    }
    return sum == n;
}

int is_deficient(int n) {
    int sum = 0;
    for (int i = 1; i < n; i++) {
        if (n % i == 0) {
            sum += i;
        }
    }
    return sum < n;
}

int is_abundant(int n) {
    int sum = 0;
    for (int i = 1; i < n; i++) {
        if (n % i == 0) {
            sum += i;
        }
    }
    return sum > n;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("NO_INPUT\n");
        return 0;
    }
    int n = atoi(argv[1]);
    if (n < 1) {
        printf("BAD_INPUT\n");
        return 0;
    }
    if (n > 1000000) {
        printf("OUT_OF_RANGE\n");
        return 0;
    }
    if (is_perfect(n)) {
        int sum = 0;
        for (int i = 1; i < n; i++) {
            if (n % i == 0) {
                sum += i;
            }
        }
        printf("n=%d sum=%d perfect\n", n, sum);
    } else if (is_deficient(n)) {
        int sum = 0;
        for (int i = 1; i < n; i++) {
            if (n % i == 0) {
                sum += i;
            }
        }
        printf("n=%d sum=%d deficient\n", n, sum);
    } else if (is_abundant(n)) {
        int sum = 0;
        for (int i = 1; i < n; i++) {
            if (n % i == 0) {
                sum += i;
            }
        }
        printf("n=%d sum=%d abundant\n", n, sum);
    }
    return 0;
}
